import{_ as a,o as e,c as r,a2 as n}from"./chunks/framework.C-si7TFR.js";const u=JSON.parse('{"title":"Agent 定时任务","description":"","frontmatter":{"title":"Agent 定时任务"},"headers":[],"relativePath":"zh/guide/schedules.md","filePath":"zh/guide/schedules.md"}'),l={name:"zh/guide/schedules.md"};function o(i,t,d,s,h,c){return e(),r("div",null,[...t[0]||(t[0]=[n('<h1 id="agent-定时任务" tabindex="-1">Agent 定时任务 <a class="header-anchor" href="#agent-定时任务" aria-label="Permalink to &quot;Agent 定时任务&quot;">​</a></h1><p>Agent 定时任务按计划向指定 Agent 提交一段任务提示词，不是工作流的 Crontab 触发器。</p><h2 id="创建任务" tabindex="-1">创建任务 <a class="header-anchor" href="#创建任务" aria-label="Permalink to &quot;创建任务&quot;">​</a></h2><ol><li>从 Agent 工作台进入<strong>定时任务</strong>，选择<strong>新建任务</strong>。</li><li>选择 Agent，填写任务名称、可选分组／描述和明确的任务提示词。</li><li>选择执行方式：执行一次、固定间隔、每天、每周或每月。</li><li>按当前表单补充执行时间、间隔或星期／日期等字段，核对页面显示的下一次执行时间。</li><li>保存，检查任务是否启用。</li></ol><p>具体时间、时区和执行范围以当前界面及运行环境为准；不要假设关机期间的任务一定补跑。</p><h2 id="立即执行与记录" tabindex="-1">立即执行与记录 <a class="header-anchor" href="#立即执行与记录" aria-label="Permalink to &quot;立即执行与记录&quot;">​</a></h2><ul><li><strong>立即执行</strong>用于验证任务，不代表周期配置已成功运行。</li><li>任务行的<strong>启用／暂停</strong>控制后续计划；已结束任务不能简单当作普通启用任务处理。</li><li><strong>执行记录</strong>展示状态、时间和异常；有最近会话时可从任务行打开关联会话。</li><li>分组、搜索和状态筛选只影响管理视图，不改变任务提示词。</li></ul><h2 id="与工作流-crontab-的区别" tabindex="-1">与工作流 Crontab 的区别 <a class="header-anchor" href="#与工作流-crontab-的区别" aria-label="Permalink to &quot;与工作流 Crontab 的区别&quot;">​</a></h2><table tabindex="0"><thead><tr><th>方式</th><th>执行对象</th><th>结果入口</th></tr></thead><tbody><tr><td>Agent 定时任务</td><td>模型推理和已授权工具的动态任务</td><td>任务运行记录及关联 Agent 会话</td></tr><tr><td><a href="./../trigger_crontab.html">工作流 Crontab</a></td><td>已编排的节点流程</td><td>工作流执行记录</td></tr></tbody></table><h2 id="无人值守前的检查" tabindex="-1">无人值守前的检查 <a class="header-anchor" href="#无人值守前的检查" aria-label="Permalink to &quot;无人值守前的检查&quot;">​</a></h2><p>先手动执行并检查结果。仅授权必要工具，限制目录和外部服务，设置清晰的任务边界。定时任务会持续使用模型与工具，可能产生费用或修改数据；异常时先暂停任务，再检查最近记录。</p>',11)])])}const b=a(l,[["render",o]]);export{u as __pageData,b as default};
